#!/usr/bin/env bash
# run.sh — Single entry point to run every experiment under experiments/.
#
# For each experiment directory, this:
#   1. Generates that experiment's tensor data (gen_data.py <experiment>)
#   2. Compiles it (<experiment>/compile.sh)
#   3. Runs it (<experiment>/run.sh --clean), which executes every compiled
#      binary, then deletes the compiled binaries.
#   4. Deletes the tensor data generated in step 1 (tensor_*.tns), since it
#      can always be regenerated by gen_data.py on the next run.
#
# The five spgemm/spmmh/spmspv/spmttkrp/spttspm "_speedup" experiments are
# the synthetic-data speedup kernels (experiments/speedups/synthetic_data/
# <kernel>/) — each compiles a plain mlir-opt --sparsifier baseline (no
# Splyce vectorization) plus Splyce's 16 phase-select/fastmath
# configurations (17 binaries total), runs every one of them, and reports
# (in speedups/synthetic_data/speedup_results.csv) every configuration's
# runtime — one row per (kernel, configuration) pair, not just the
# fastest. phase_ablation instead writes its own richer TMA breakdown
# (phase_ablation/tma_results.csv), multicore its own core-count scaling
# results (multicore/results.csv), sparsity_scaling its own density-sweep
# results (sparsity_scaling/results.csv), and vector_width its own
# vector-width-sweep results (vector_width/results.csv) — see each one's
# own run.sh.
#
# Add new experiment names to EXPERIMENTS (and their directory in
# EXPERIMENT_DIR) as they're set up — each needs a compile.sh and a run.sh,
# and a matching generator in gen_data.py.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"

EXPERIMENTS=(
#   phase_ablation
  # multicore
  # sparsity_scaling
  vector_width
  # spgemm_speedup
  # spmmh_speedup
  # spmspv_speedup
  # spmttkrp_speedup
  # spttspm_speedup
)

declare -A EXPERIMENT_DIR=(
  [phase_ablation]="phase_ablation"
  [multicore]="multicore"
  [sparsity_scaling]="sparsity_scaling"
  [vector_width]="vector_width"
  [spgemm_speedup]="speedups/synthetic_data/spgemm"
  [spmmh_speedup]="speedups/synthetic_data/spmmh"
  [spmspv_speedup]="speedups/synthetic_data/spmspv"
  [spmttkrp_speedup]="speedups/synthetic_data/spmttkrp"
  [spttspm_speedup]="speedups/synthetic_data/spttspm"
)

SPEEDUP_RESULTS="$SCRIPT_DIR/speedups/synthetic_data/speedup_results.csv"
echo "kernel,configuration,exec_time_s" > "$SPEEDUP_RESULTS"

for experiment in "${EXPERIMENTS[@]}"; do
  exp_dir="$SCRIPT_DIR/${EXPERIMENT_DIR[$experiment]}"

  echo "========================================"
  echo " Experiment: $experiment"
  echo "========================================"

  echo "[$experiment] Generating tensor data ..."
  python3 "$SCRIPT_DIR/gen_data.py" "$experiment"

  echo "[$experiment] Compiling ..."
  ( cd "$exp_dir" && ./compile.sh )

  echo "[$experiment] Running ..."
  if [[ "$experiment" == "phase_ablation" || "$experiment" == "multicore" || "$experiment" == "sparsity_scaling" || "$experiment" == "vector_width" ]]; then
    ( cd "$exp_dir" && ./run.sh --clean )
  else
    ( cd "$exp_dir" && ./run.sh --clean "$SPEEDUP_RESULTS" )
  fi

  echo "[$experiment] Deleting tensor data ..."
  rm -f "$exp_dir"/tensor_*.tns

  echo "[$experiment] Done. Results in $exp_dir"
  echo ""
done

echo "Speedup summary (every configuration's runtime, per kernel): $SPEEDUP_RESULTS"
